const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([-140, 0]).buffer(50000); // 50km buffer around the point in the equatorial Pacific
  const startDate1 = '1998-08-01';
  const endDate1 = '1998-08-31';
  const startDate2 = '1999-12-01';
  const endDate2 = '1999-12-31';
  const collectionName = 'NASA/OCEANDATA/SeaWiFS/L3SMI';
  const bandName = 'chlor_a';

  // 2. Data Acquisition & Check
  const col1 = ee.ImageCollection(collectionName)
    .filterBounds(aoi)
    .filterDate(startDate1, endDate1)
    .select(bandName);

  const col2 = ee.ImageCollection(collectionName)
    .filterBounds(aoi)
    .filterDate(startDate2, endDate2)
    .select(bandName);

  const col1Size = col1.size().getInfo();
  const col2Size = col2.size().getInfo();

  if (col1Size === 0 || col2Size === 0) {
    console.log(`Image count for Aug 1998: ${col1Size}`);
    console.log(`Image count for Dec 1999: ${col2Size}`);
    console.log("Empty collection for one or both periods.");
    console.log("C1");
    return;
  }
  console.log(`Image count for Aug 1998: ${col1Size}`);
  console.log(`Image count for Dec 1999: ${col2Size}`);

  // 3. Processing and Calculation
  const image1 = col1.mean();
  const image2 = col2.mean();

  const reducers = ee.Reducer.mean().combine({
    reducer2: ee.Reducer.count(),
    sharedInputs: true
  });

  const stats1 = image1.reduceRegion({
    reducer: reducers,
    geometry: aoi,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = image2.reduceRegion({
    reducer: reducers,
    geometry: aoi,
    scale: 4000,
    maxPixels: 1e9
  }).getInfo();

  const val1 = stats1 ? stats1[bandName + '_mean'] : null;
  const count1 = stats1 ? stats1[bandName + '_count'] : 0;
  const val2 = stats2 ? stats2[bandName + '_mean'] : null;
  const count2 = stats2 ? stats2[bandName + '_count'] : 0;

  // 4. Validation
  if (count1 === 0 || count2 === 0) {
    console.log(`Valid pixels for Aug 1998: ${count1}`);
    console.log(`Valid pixels for Dec 1999: ${count2}`);
    console.log("No valid pixels found after processing.");
    console.log("C2");
    return;
  }
   console.log(`Valid pixels for Aug 1998: ${count1}`);
   console.log(`Valid pixels for Dec 1999: ${count2}`);

  if (val1 === null || val2 === null) {
    console.log("Could not calculate mean chlorophyll value.");
    console.log("C3");
    return;
  }

  // 5. Final Answer
  console.log(`Aug 1998 Chlorophyll (mg/m^3): ${val1.toFixed(3)}`);
  console.log(`Dec 1999 Chlorophyll (mg/m^3): ${val2.toFixed(3)}`);

  if (val2 < val1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

